package ru.screenrecorder.app;
import android.content.*;import android.graphics.Rect;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.util.DisplayMetrics;import android.view.*;import java.nio.*;import java.util.*;
final class RecorderEngine {
 final Context context;final MediaProjection projection;final boolean mic,internal;volatile float gain;final int quality;
 volatile boolean stopped,paused;volatile Exception failure;long pauseAt,pausedUs,firstVideo=-1,lastVideo=-1;long audioFrames;
 MediaCodec video,audio;MediaMuxer muxer;android.os.ParcelFileDescriptor fd;Surface surface;VirtualDisplay display;AudioRecord microphone,playback;Uri uri;Thread videoThread,audioThread;int videoTrack=-1,audioTrack=-1;boolean muxStarted;final List<Packet> queued=new ArrayList<>();int queuedBytes;
 static final class Packet{int track;byte[] bytes;MediaCodec.BufferInfo info;Packet(int t,byte[]b,MediaCodec.BufferInfo i){track=t;bytes=b;info=i;}}
 RecorderEngine(Context c,MediaProjection p,boolean m,boolean s,int g,int q){context=c;projection=p;mic=m;internal=s;gain=Math.max(0,Math.min(100,g))/100f;quality=q;}
 void start()throws Exception{
  projection.registerCallback(new MediaProjection.Callback(){public void onStop(){if(RecordingService.active!=null)RecordingService.active.finish();}},new Handler(Looper.getMainLooper()));
  DisplayMetrics dm=new DisplayMetrics();((WindowManager)context.getSystemService(Context.WINDOW_SERVICE)).getDefaultDisplay().getRealMetrics(dm);
  int limit=quality==0?1280:1920,fps=quality==2?60:quality==0?15:30;double scale=Math.min(1.,limit/(double)Math.max(dm.widthPixels,dm.heightPixels));int w=Math.max(2,((int)(dm.widthPixels*scale))&~1),h=Math.max(2,((int)(dm.heightPixels*scale))&~1);
  ContentValues cv=new ContentValues();cv.put(MediaStore.Video.Media.DISPLAY_NAME,"Запись_"+new java.text.SimpleDateFormat("yyyy-MM-dd_HH-mm-ss",Locale.ROOT).format(new Date())+".mp4");cv.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");cv.put(MediaStore.Video.Media.RELATIVE_PATH,"Movies/ScreenRecorder");cv.put(MediaStore.Video.Media.IS_PENDING,1);uri=context.getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,cv);if(uri==null)throw new Exception("Не удалось создать видео");
  try{
   fd=context.getContentResolver().openFileDescriptor(uri,"rw");muxer=new MediaMuxer(fd.getFileDescriptor(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);
   MediaFormat vf=MediaFormat.createVideoFormat("video/avc",w,h);vf.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface);vf.setInteger(MediaFormat.KEY_BIT_RATE,quality==0?2500000:quality==1?6000000:10000000);vf.setInteger(MediaFormat.KEY_FRAME_RATE,fps);vf.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);
   video=MediaCodec.createEncoderByType("video/avc");video.configure(vf,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);surface=video.createInputSurface();video.start();
   if(mic||internal){MediaFormat af=MediaFormat.createAudioFormat("audio/mp4a-latm",48000,1);af.setInteger(MediaFormat.KEY_AAC_PROFILE,MediaCodecInfo.CodecProfileLevel.AACObjectLC);af.setInteger(MediaFormat.KEY_BIT_RATE,128000);audio=MediaCodec.createEncoderByType("audio/mp4a-latm");audio.configure(af,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);audio.start();if(mic)microphone=record(false);if(internal)playback=record(true);}
   display=projection.createVirtualDisplay("ScreenRecorder",w,h,dm.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,surface,null,new Handler(Looper.getMainLooper()));
   videoThread=new Thread(()->videoLoop(),"video-encoder");videoThread.start();if(audio!=null){audioThread=new Thread(()->audioLoop(),"audio-encoder");audioThread.start();}
  }catch(Exception e){failure=e;throw e;}
 }
 AudioRecord record(boolean system)throws Exception{
  AudioFormat format=new AudioFormat.Builder().setEncoding(AudioFormat.ENCODING_PCM_16BIT).setSampleRate(48000).setChannelMask(AudioFormat.CHANNEL_IN_MONO).build();
  AudioRecord.Builder b=new AudioRecord.Builder().setAudioFormat(format).setBufferSizeInBytes(Math.max(16384,AudioRecord.getMinBufferSize(48000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT)*4));
  if(system)b.setAudioPlaybackCaptureConfig(new AudioPlaybackCaptureConfiguration.Builder(projection).addMatchingUsage(AudioAttributes.USAGE_MEDIA).addMatchingUsage(AudioAttributes.USAGE_GAME).addMatchingUsage(AudioAttributes.USAGE_UNKNOWN).build());else b.setAudioSource(MediaRecorder.AudioSource.MIC);
  AudioRecord r=b.build();if(r.getState()!=AudioRecord.STATE_INITIALIZED){r.release();throw new Exception(system?"Недоступен внутренний звук":"Недоступен микрофон");}r.startRecording();return r;
 }
 synchronized void setPaused(boolean p){if(stopped||p==paused)return;if(p){pauseAt=SystemClock.elapsedRealtimeNanos()/1000;paused=true;}else{pausedUs+=SystemClock.elapsedRealtimeNanos()/1000-pauseAt;Bundle b=new Bundle();b.putInt(MediaCodec.PARAMETER_KEY_REQUEST_SYNC_FRAME,0);video.setParameters(b);waitingKey=true;paused=false;}}
 volatile boolean waitingKey;
 void videoLoop(){boolean eosSent=false;long deadline=Long.MAX_VALUE;try{MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(true){if(stopped&&!eosSent){video.signalEndOfInputStream();eosSent=true;deadline=SystemClock.elapsedRealtime()+5000;}
   int n=video.dequeueOutputBuffer(info,20000);if(n==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){format(false,video.getOutputFormat());continue;}if(n>=0){boolean key=(info.flags&MediaCodec.BUFFER_FLAG_KEY_FRAME)!=0;if(!paused&&(!waitingKey||key)){waitingKey=false;if(firstVideo<0)firstVideo=info.presentationTimeUs;long pts=Math.max(lastVideo+1,info.presentationTimeUs-firstVideo-pausedUs);lastVideo=pts;packet(video,n,info,videoTrack,pts);}boolean end=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;video.releaseOutputBuffer(n,false);if(end)break;}if(eosSent&&SystemClock.elapsedRealtime()>deadline)throw new Exception("Тайм-аут видеоэнкодера");}
  }catch(Exception e){fail(e);}}
 void audioLoop(){try{short[] m=new short[960],s=new short[960];long clock=SystemClock.elapsedRealtimeNanos()/1000;while(!stopped){
   if(paused){if(microphone!=null)microphone.read(m,0,m.length,AudioRecord.READ_NON_BLOCKING);if(playback!=null)playback.read(s,0,s.length,AudioRecord.READ_NON_BLOCKING);Thread.sleep(10);continue;}
   long target=(SystemClock.elapsedRealtimeNanos()/1000-clock-pausedUs)*48000/1000000;if(audioFrames>=target){drainAudio(false);Thread.sleep(5);continue;}int count=(int)Math.min(960,target-audioFrames);
   int nm=microphone==null?0:microphone.read(m,0,count,AudioRecord.READ_NON_BLOCKING),ns=playback==null?0:playback.read(s,0,count,AudioRecord.READ_NON_BLOCKING);if(nm<0||ns<0)throw new Exception("Аудиоустройство отключено");
   int input=audio.dequeueInputBuffer(10000);if(input<0){drainAudio(false);continue;}ByteBuffer dst=audio.getInputBuffer(input);dst.clear();dst.order(ByteOrder.LITTLE_ENDIAN);count=Math.min(count,dst.remaining()/2);int peak=0;
   for(int k=0;k<count;k++){float a=k<nm?m[k]*gain:0,b=k<ns?s[k]:0;peak=Math.max(peak,(int)Math.abs(a));int value=Math.round((a+b)*(mic&&internal?.7f:1f));dst.putShort((short)Math.max(-32768,Math.min(32767,value)));}RecordingService.level=Math.min(100,peak*100/32768);audio.queueInputBuffer(input,0,count*2,audioFrames*1000000/48000,0);audioFrames+=count;drainAudio(false);
  }
  long timeout=SystemClock.elapsedRealtime()+5000;boolean sent=false;while(SystemClock.elapsedRealtime()<timeout){if(!sent){int in=audio.dequeueInputBuffer(10000);if(in>=0){audio.queueInputBuffer(in,0,0,audioFrames*1000000/48000,MediaCodec.BUFFER_FLAG_END_OF_STREAM);sent=true;}}if(drainAudio(sent))return;}throw new Exception("Тайм-аут аудиоэнкодера");
 }catch(Exception e){fail(e);}}
 boolean drainAudio(boolean wait)throws Exception{MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(true){int n=audio.dequeueOutputBuffer(info,wait?10000:0);if(n==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){format(true,audio.getOutputFormat());continue;}if(n<0)return false;packet(audio,n,info,audioTrack,info.presentationTimeUs);boolean end=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;audio.releaseOutputBuffer(n,false);if(end)return true;}}
 synchronized void format(boolean sound,MediaFormat f){int t=muxer.addTrack(f);if(sound)audioTrack=t;else videoTrack=t;if(videoTrack>=0&&(!(mic||internal)||audioTrack>=0)){muxer.start();muxStarted=true;for(Packet p:queued)muxer.writeSampleData(p.track,ByteBuffer.wrap(p.bytes),p.info);queued.clear();queuedBytes=0;}}
 synchronized void packet(MediaCodec codec,int n,MediaCodec.BufferInfo input,int track,long pts)throws Exception{if(input.size==0||(input.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0)return;if(track<0)throw new Exception("Не получен формат дорожки");ByteBuffer b=codec.getOutputBuffer(n);b.position(input.offset);b.limit(input.offset+input.size);b=b.slice();MediaCodec.BufferInfo i=new MediaCodec.BufferInfo();i.set(0,input.size,pts,input.flags);if(muxStarted)muxer.writeSampleData(track,b,i);else{byte[] bytes=new byte[input.size];b.get(bytes);queuedBytes+=bytes.length;if(queuedBytes>8000000)throw new Exception("Не удалось начать MP4");queued.add(new Packet(track,bytes,i));}}
 void fail(Exception e){failure=e;stopped=true;if(RecordingService.active!=null)RecordingService.active.finish();}
 Uri stop()throws Exception{stopped=true;if(videoThread!=null&&videoThread!=Thread.currentThread())videoThread.join(7000);if(audioThread!=null&&audioThread!=Thread.currentThread())audioThread.join(7000);Exception error=failure;
  if(videoThread!=null&&videoThread.isAlive()||audioThread!=null&&audioThread.isAlive())error=new Exception("Запись не завершилась вовремя");
  if(display!=null)display.release();for(AudioRecord r:new AudioRecord[]{microphone,playback})if(r!=null){try{r.stop();}catch(Exception ignored){}r.release();}for(MediaCodec c:new MediaCodec[]{video,audio})if(c!=null){try{c.stop();}catch(Exception ignored){}c.release();}if(surface!=null)surface.release();if(muxer!=null){try{if(muxStarted)muxer.stop();else error=new Exception("Не получено видео");}catch(Exception e){error=e;}muxer.release();}if(fd!=null)fd.close();if(projection!=null)projection.stop();
  if(uri!=null){if(error!=null){context.getContentResolver().delete(uri,null,null);throw error;}ContentValues done=new ContentValues();done.put(MediaStore.Video.Media.IS_PENDING,0);context.getContentResolver().update(uri,done,null,null);}return uri;
 }
}
